window.LESSONS = [{"slug":"english","name":"English","tryHash":"#/subject/english","topics":[{"id":"comprehension-and-summary","title":"Comprehension and summary","summary":"Read the passage once for the gist, then answer questions that test main points, implied meaning and the writer's tone or intention","points":["Read the passage once for the gist, then answer questions that test main points, implied meaning and the writer's tone or intention. Summary: keep main points only, in your own words, with no new information.","Watch out: Do not pick an answer just because it uses words from the passage","Watch out: Answers are often in the paragraph's topic sentence"],"tip":"Do not pick an answer just because it uses words from the passage","example":"If a writer says the government 'turned a blind eye', the implied meaning is that the government ignored the problem."},{"id":"cloze-passage","title":"Cloze passage","summary":"A cloze test has gaps","points":["A cloze test has gaps. Read the whole passage first, then choose the word that fits the meaning and grammar of each gap.","Watch out: Check tense, number and collocation (e.g. 'make a decision', not 'do')","Watch out: Read the sentence after the gap, not only before"],"tip":"Check tense, number and collocation (e.g. 'make a decision', not 'do')","example":"'She was ___ with joy' needs an adjective like 'filled', not a noun."},{"id":"synonyms-and-antonyms","title":"Synonyms and antonyms","summary":"Synonyms have the same meaning, antonyms the opposite","points":["Synonyms have the same meaning, antonyms the opposite. Context decides the meaning of a word with more than one sense.","Watch out: Opposites with prefixes (happy/unhappy) are not always right","Watch out: Context can change a word's meaning"],"tip":"Opposites with prefixes (happy/unhappy) are not always right","example":"Antonym of 'ancient' is 'modern'; synonym of 'ancient' is 'old'."},{"id":"word-classes-and-sentence-patterns","title":"Word classes and sentence patterns","summary":"Nouns, pronouns, verbs, adjectives, adverbs, prepositions, conjunctions, interjections","points":["Nouns, pronouns, verbs, adjectives, adverbs, prepositions, conjunctions, interjections. A sentence has a subject and a predicate. Simple, compound and complex sentences.","Watch out: 'Run' can be a noun or verb depending on use","Watch out: Subject-verb agreement: 'he goes', 'they go'"],"tip":"'Run' can be a noun or verb depending on use","example":"In 'The boy ran quickly', 'quickly' is an adverb."},{"id":"tense-aspect-mood-and-concord","title":"Tense, aspect, mood and concord","summary":"Tense = time (past, present, future)","points":["Tense = time (past, present, future). Aspect = completed or continuous. Mood = indicative, imperative, subjunctive. Concord = subject and verb agree in number. Question tags: 'He is coming, isn't he?'","Watch out: Collective nouns can take singular or plural verb (committee is)","Watch out: 'Neither/nor' takes the verb nearer the subject"],"tip":"Collective nouns can take singular or plural verb (committee is)","example":"'If I were rich' uses the subjunctive."},{"id":"degree-of-comparison-and-idioms","title":"Degree of comparison and idioms","summary":"Positive, comparative (-er/more), superlative (-est/most)","points":["Positive, comparative (-er/more), superlative (-est/most). Idioms have meanings different from their words: 'break the ice' means start a conversation.","Watch out: Do not double the comparative ('more better')","Watch out: Idioms must be in standard British English for JAMB"],"tip":"Do not double the comparative ('more better')","example":"Good, better, best."},{"id":"spelling-and-mechanics","title":"Spelling and mechanics","summary":"Spelling rules and correct use of capital letters, punctuation, apostrophes and hyphens.","points":["Spelling rules and correct use of capital letters, punctuation, apostrophes and hyphens.","Watch out: Their/there/they're","Watch out: Affect (verb) vs effect (noun)"],"tip":"Their/there/they're","example":"'its' is possessive; 'it's' means 'it is'."},{"id":"oral-forms-vowels-and-consonants","title":"Oral forms: vowels and consonants","summary":"Monophthongs are one pure vowel sound","points":["Monophthongs are one pure vowel sound. Diphthongs glide from one vowel to another (/ai/ as in 'five'). Triphthongs glide across three vowels. Consonants: voiced (vibrate vocal cords, /b/) or voiceless (/p/).","Watch out: Count sounds, not letters ('ship' has 3 sounds)","Watch out: Consonant clusters: 'str' in 'street'"],"tip":"Count sounds, not letters ('ship' has 3 sounds)","example":"'Boy' has the diphthong /oi/."},{"id":"rhymes-homophones-and-stress","title":"Rhymes, homophones and stress","summary":"Rhymes share the final sound","points":["Rhymes share the final sound. Homophones sound alike but differ in meaning (sea/see). Word stress: place the stress on the correct syllable (PRE-sent noun vs pre-SENT verb). Emphatic stress highlights one word in a sentence.","Watch out: Stress can change the word class","Watch out: Rhymes depend on sound, not spelling"],"tip":"Stress can change the word class","example":"'Record' as noun: REC-ord; as verb: re-CORD."},{"id":"word-stress-where-the-main-beat-falls","title":"Word stress: where the main beat falls","summary":"Every word of two or more syllables has one main stressed syllable: it is longer, louder and higher","points":["Every word of two or more syllables has one main stressed syllable: it is longer, louder and higher. Stress is not shown in spelling, so learn where it falls. Most two-syllable nouns stress the first syllable (TAble, PREsent). Most two-syllable verbs stress the second (preSENT, deCIDE).","Watch out: Stress can change the word class: same spelling, different stress","Watch out: Prefixes such as re-, de- and un- are usually not stressed"],"tip":"Stress can change the word class: same spelling, different stress","example":"REcord (noun) and reCORD (verb); OBject (noun) and obJECT (verb)."},{"id":"stress-and-suffixes-the-stress-moves","title":"Stress and suffixes: the stress moves","summary":"Some suffixes move the stress","points":["Some suffixes move the stress. Words ending in -ic, -ity, -ion, -ian, -ify or -ial usually stress the syllable just BEFORE the suffix. Compound nouns usually stress the first part.","Watch out: Do not stress the -ion syllable itself: stress the one before it","Watch out: Compound adjectives can take stress on the second part: well-KNOWN"],"tip":"Do not stress the -ion syllable itself: stress the one before it","example":"PHOtograph becomes phoTOgraphy; eCONomy becomes ecoNOMic; GREENhouse, BLACKboard."},{"id":"intonation-rising-and-falling-tones","title":"Intonation: rising and falling tones","summary":"Intonation is the pitch movement across a sentence","points":["Intonation is the pitch movement across a sentence. Falling tone: statements, wh-questions, commands, greetings. Rising tone: yes/no questions, lists (non-final items), surprise or disbelief. Fall-rise: doubt, contrast or reservation.","Watch out: Wh-questions usually fall; yes/no questions usually rise","Watch out: A tag question with a falling tone expects agreement; with a rising tone it asks a real question"],"tip":"Wh-questions usually fall; yes/no questions usually rise","example":"Are you ready? (rising). What is your name? (falling). Sit down. (falling)."},{"id":"vowel-sounds-short-long-monophthongs-and","title":"Vowel sounds: short, long, monophthongs and diphthongs","summary":"English has 12 pure vowels (monophthongs) and 8 glides (diphthongs)","points":["English has 12 pure vowels (monophthongs) and 8 glides (diphthongs). Short vowels are relaxed: /ɪ/ in bit, /e/ in bed, /æ/ in cat, /ʌ/ in cut, /ɒ/ in hot, /ʊ/ in full. Long vowels are held: /iː/ in sheep, /ɑː/ in car, /ɔː/ in door, /uː/ in fool, /ɜː/ in bird. Diphthongs glide: /eɪ/ day, /aɪ/ five, /ɔɪ/ boy, /əʊ/ go, /aʊ/ now.","Watch out: Count sounds, not letters: ship has 3 sounds, box has 4","Watch out: Long vs short vowel changes meaning: ship vs sheep"],"tip":"Count sounds, not letters: ship has 3 sounds, box has 4","example":"bit /bɪt/ vs beat /biːt/: the vowel length changes the word."},{"id":"minimal-pairs-and-consonant-sounds","title":"Minimal pairs and consonant sounds","summary":"A minimal pair is two words that differ by ONE sound: pin/bin, ship/sheep, lice/rice","points":["A minimal pair is two words that differ by ONE sound: pin/bin, ship/sheep, lice/rice. Voiced consonants (/b d g v z/) vibrate the vocal cords; voiceless ones (/p t k f s/) do not. Other key contrasts: /θ/ think vs /ð/ this; /tʃ/ chin vs /ʃ/ shin; /l/ vs /r/.","Watch out: Spelling can hide the sound: hour starts with a silent h","Watch out: Consonant clusters count as separate sounds: street has 5 sounds"],"tip":"Spelling can hide the sound: hour starts with a silent h","example":"bus /bʌs/ vs buzz /bʌz/: only the final voiced consonant differs."}]},{"slug":"maths","name":"Mathematics","tryHash":"#/subject/maths","topics":[{"id":"number-bases","title":"Number bases","summary":"A base-b number uses digits 0 to b-1","points":["A base-b number uses digits 0 to b-1. Convert to base 10 by multiplying each digit by the power of its place. Convert from base 10 by repeated division by the base.","Formula: (abc)b = a x b2 + b x b + c","Watch out: Base-2 digits are only 0 and 1","Watch out: Check that every digit is less than the base"],"tip":"Base-2 digits are only 0 and 1","example":"(101)2 = 1x4 + 0x2 + 1 = 5 in base 10."},{"id":"fractions-decimals-percentages-and-vat","title":"Fractions, decimals, percentages and VAT","summary":"Percentage = part / whole × 100","points":["Percentage = part / whole × 100. Simple interest: I = PRT/100. Profit % = profit / cost price × 100. VAT is added to the price, usually 7.5% in Nigeria.","Formula: I = PRT / 100","Formula: Profit % = (SP - CP)/CP × 100","Formula: Price with VAT = P x 1.075","Watch out: Percentage change is based on the original value","Watch out: Round as instructed (significant figures vs decimal places)"],"tip":"Percentage change is based on the original value","example":"A N2000 item with 7.5% VAT costs 2000 × 1.075 = N2150."},{"id":"indices-logarithms-and-surds","title":"Indices, logarithms and surds","summary":"Laws of indices: a^m x a^n = a^(m+n), a^m / a^n = a^(m-n), (a^m)^n = a^(mn)","points":["Laws of indices: a^m x a^n = a^(m+n), a^m / a^n = a^(m-n), (a^m)^n = a^(mn). log(ab) = log a + log b; log(a/b) = log a - log b; log a^n = n log a. Surds are irrational roots; rationalise the denominator by multiplying by the conjugate.","Formula: log_b a = log a / log b","Watch out: log(a+b) is not log a + log b","Watch out: √(a+b) is not √a + √b"],"tip":"log(a+b) is not log a + log b","example":"log 100 = 2 (since 10² = 100)."},{"id":"sets-and-venn-diagrams","title":"Sets and Venn diagrams","summary":"A set is a collection of distinct objects","points":["A set is a collection of distinct objects. Union (U), intersection (n), complement (A'). Use Venn diagrams for up to three sets, fill the intersection first, then work outwards.","Formula: n(A U B) = n(A) + n(B) - n(A n B)","Watch out: Fill the intersection first","Watch out: Empty set is written as {} or phi"],"tip":"Fill the intersection first","example":"If 10 like tea, 8 like coffee, 3 like both, 15 like at least one? Total = 10+8-3 = 15."},{"id":"polynomials-factor-and-remainder-theorem","title":"Polynomials, factor and remainder theorems","summary":"Factor theorem: (x - a) is a factor if f(a) = 0","points":["Factor theorem: (x - a) is a factor if f(a) = 0. Remainder theorem: remainder when f(x) is divided by (x - a) is f(a). Solve simultaneous equations one linear, one quadratic by substitution.","Formula: Difference of squares: a2 - b2 = (a-b)(a+b)","Watch out: Check the sign: f(a) with a = -2 for factor (x + 2)","Watch out: Substitute the linear equation into the quadratic"],"tip":"Check the sign: f(a) with a = -2 for factor (x + 2)","example":"f(x) = x² - 5x + 6, f(2) = 0, so (x - 2) is a factor."},{"id":"variation","title":"Variation","summary":"Direct: y = kx","points":["Direct: y = kx. Inverse: y = k/x. Joint: y = kxz. Partial: y depends on x and z separately. Find k from given values first.","Formula: y = kx; y = k/x; y = kxz","Watch out: Find k first before the second case","Watch out: Percentage increase = (new - old)/old × 100"],"tip":"Find k first before the second case","example":"y is inversely proportional to x. If x = 2, y = 6, then k = 12, so y = 12/x."},{"id":"inequalities","title":"Inequalities","summary":"Solve linear inequalities like a normal equation, but flip the sign when multiplying or dividing by a negative","points":["Solve linear inequalities like a normal equation, but flip the sign when multiplying or dividing by a negative. Quadratic inequalities: find roots, then decide where the curve is above or below zero.","Watch out: Forgetting to flip the inequality sign for negatives","Watch out: Use open circles for < and >, closed for <= and >="],"tip":"Forgetting to flip the inequality sign for negatives","example":"-2x > 6 gives x < -3 (sign flips)."},{"id":"progressions","title":"Progressions","summary":"Arithmetic progression: nth term a + (n-1)d, sum S = n/2 (2a + (n-1)d)","points":["Arithmetic progression: nth term a + (n-1)d, sum S = n/2 (2a + (n-1)d). Geometric progression: nth term ar^(n-1), sum S = a(r^n - 1)/(r - 1). Sum to infinity exists if |r| < 1: S = a/(1 - r).","Formula: AP: Tn = a + (n-1)d","Formula: GP: Tn = ar^(n-1)","Formula: S_inf = a/(1-r)","Watch out: Identify whether AP or GP first","Watch out: Sum to infinity needs |r| < 1"],"tip":"Identify whether AP or GP first","example":"GP with a = 2, r = 3: T4 = 2 × 27 = 54."},{"id":"matrices-and-determinants","title":"Matrices and determinants","summary":"A matrix is a rectangular array","points":["A matrix is a rectangular array. Determinant of 2x2 [a b; c d] = ad - bc. Inverse of 2x2 = (1/det) [d -b; -c a]. If det = 0, no inverse.","Formula: det = ad - bc","Formula: Inverse = 1/(ad-bc) x [d -b; -c a]","Watch out: Inverse exists only if determinant is not zero","Watch out: Matrix multiplication is not commutative"],"tip":"Inverse exists only if determinant is not zero","example":"[2 1; 1 1] has det = 2 - 1 = 1, inverse [1 -1; -1 2]."},{"id":"coordinate-geometry","title":"Coordinate geometry","summary":"Midpoint = ((x1+x²)/2, (y1+y²)/2)","points":["Midpoint = ((x1+x²)/2, (y1+y²)/2). Gradient m = (y² - y1)/(x² - x1). Parallel lines have equal gradients; perpendicular lines have m1 x m2 = -1. Line forms: y = mx + c, y - y1 = m(x - x1).","Formula: Distance = √((x²-x1)2 + (y²-y1)2)","Watch out: Gradient is change in y over change in x (not x over y)","Watch out: Perpendicular gradient is negative reciprocal"],"tip":"Gradient is change in y over change in x (not x over y)","example":"Points (1,2) and (4,6): distance = √(9+16) = 5."},{"id":"trigonometry","title":"Trigonometry","summary":"SOH CAH TOA: sin = opp/hyp, cos = adj/hyp, tan = opp/adj","points":["SOH CAH TOA: sin = opp/hyp, cos = adj/hyp, tan = opp/adj. Sine rule: a/sinA = b/sinB. Cosine rule: a2 = b2 + c2 - 2bc cosA. Area = 1/2 ab sin C. Angles of elevation and depression are measured from the horizontal.","Formula: sin2 + cos2 = 1","Formula: Area = 1/2 ab sin C","Watch out: Check calculator is in degree mode","Watch out: Depression and elevation are equal (alternate angles)"],"tip":"Check calculator is in degree mode","example":"Tower 30 m high, angle of elevation 45 degrees, distance = 30 m."},{"id":"mensuration","title":"Mensuration","summary":"Area and perimeter of plane figures","points":["Area and perimeter of plane figures. Circle: area π r², circumference 2 π r. Sector: area = θ/360 x π r². Volume: cylinder π r² h, cone 1/3 π r² h, sphere 4/3 π r³. Surface area of solids.","Formula: Arc length = θ/360 × 2 π r","Formula: Sphere: 4 π r² surface area","Watch out: Use the radius, not the diameter","Watch out: Use π = 22/7 or 3.142 as instructed"],"tip":"Use the radius, not the diameter","example":"Cylinder radius 7 cm, height 10 cm: volume = 22/7 × 49 ×10 = 1540 cm3."},{"id":"statistics-and-probability","title":"Statistics and probability","summary":"Mean = sum / count","points":["Mean = sum / count. Median is the middle value (sort first). Mode is the most frequent. Probability = favourable / total. P(A or B) = P(A) + P(B) if mutually exclusive. P(A and B) = P(A) x P(B) if independent.","Formula: Mean = sum of fx / sum of f","Watch out: Median for even count is the average of two middle values","Watch out: Probabilities add to 1"],"tip":"Median for even count is the average of two middle values","example":"Coin tossed twice: P(two heads) = 1/2 × 1/2 = 1/4."},{"id":"money-shares-and-earnings","title":"Money, shares and earnings","summary":"Shares: dividend = number of shares x dividend per share","points":["Shares: dividend = number of shares x dividend per share. Earnings: net pay = gross - deductions. Commission and discount are percentages of the base amount.","Formula: Dividend = shares x rate","Watch out: Discount is taken off the marked price, not the cost","Watch out: Commission is on sales value"],"tip":"Discount is taken off the marked price, not the cost","example":"100 shares paying N5 each: dividend = N500."}]},{"slug":"biology","name":"Biology","tryHash":"#/subject/biology","topics":[{"id":"living-organisms-and-cell-structure","title":"Living organisms and cell structure","summary":"Living things: movement, respiration, sensitivity, growth, reproduction, excretion, nutrition","points":["Living things: movement, respiration, sensitivity, growth, reproduction, excretion, nutrition. Plant cells have cell wall, chloroplast, large vacuole. Animal cells lack these. Levels: cell, tissue, organ, system, organism.","Watch out: Viruses are not considered living by many textbooks","Watch out: Plant cells have cell wall, animal cells do not"],"tip":"Viruses are not considered living by many textbooks","example":"A leaf cell has chloroplasts; a nerve cell does not need them."},{"id":"classification-and-evolution-of-organism","title":"Classification and evolution of organisms","summary":"Kingdoms: Monera (bacteria), Protista (protozoans, algae), Fungi, Plantae (mosses, ferns, seed plants), Animalia (invertebrates, vertebrates)","points":["Kingdoms: Monera (bacteria), Protista (protozoans, algae), Fungi, Plantae (mosses, ferns, seed plants), Animalia (invertebrates, vertebrates). Plants evolved from water to land. Bryophytes have no true roots; pteridophytes have true roots but no seeds; spermatophytes have seeds.","Watch out: Fungi are not plants (no chlorophyll)","Watch out: Binomial name: genus + species, italic, Homo sapiens"],"tip":"Fungi are not plants (no chlorophyll)","example":"Mushroom: Fungi. Amoeba: Protista."},{"id":"adaptations-of-organisms","title":"Adaptations of organisms","summary":"Structural adaptations are body shapes or parts; functional are processes; behavioural are actions","points":["Structural adaptations are body shapes or parts; functional are processes; behavioural are actions. Countershading and warning colours protect. Social insects have castes (queen, worker, soldier).","Watch out: Adaptation is an inherited trait, not an acquired one","Watch out: Warning colours are bright; camouflage blends in"],"tip":"Adaptation is an inherited trait, not an acquired one","example":"Cactus spines reduce water loss: structural adaptation."},{"id":"internal-structure-of-plants-and-mammals","title":"Internal structure of plants and mammals","summary":"Root, stem and leaf have specific tissues","points":["Root, stem and leaf have specific tissues. Xylem carries water up, phloem carries food down. Mammal organs: digestive, excretory, reproductive systems are arranged in the body cavity.","Watch out: Phloem carries sucrose both ways","Watch out: Xylem is dead tissue at maturity"],"tip":"Phloem carries sucrose both ways","example":"Xylem is the water-carrying tissue, found in the stem and root."},{"id":"nutrition","title":"Nutrition","summary":"Autotrophs make their own food (photosynthesis, chemosynthesis)","points":["Autotrophs make their own food (photosynthesis, chemosynthesis). Heterotrophs eat food (holozoic, parasitic, saprophytic, carnivorous). Photosynthesis light reaction makes ATP and O2; dark reaction fixes CO2. Food tests: starch (iodine turns blue-black), protein (biuret violet), reducing sugar (Benedict's brick red), fat (emulsion milky).","Formula: 6CO2 + 6H2O gives C6H12O6 + 6O2","Watch out: Light reactions need light, dark reactions do not","Watch out: Kwashiorkor: protein deficiency; marasmus: total starvation"],"tip":"Light reactions need light, dark reactions do not","example":"Iodine on a leaf in the dark: no blue-black, because no starch was made."},{"id":"transport","title":"Transport","summary":"Mammals use a double circulation: heart, arteries, veins, capillaries","points":["Mammals use a double circulation: heart, arteries, veins, capillaries. Plants use xylem (water up, transpiration pull) and phloem (food, translocation). Diffusion, osmosis, plasmolysis, turgidity are passive; active transport uses energy.","Watch out: Pulmonary vein carries oxygenated blood; pulmonary artery carries deoxygenated","Watch out: Osmosis is diffusion of water only"],"tip":"Pulmonary vein carries oxygenated blood; pulmonary artery carries deoxygenated","example":"Red blood cell in pure water swells and bursts (haemolysis)."},{"id":"respiration","title":"Respiration","summary":"Aerobic respiration: glucose + O2 gives CO2 + H2O + energy (ATP)","points":["Aerobic respiration: glucose + O2 gives CO2 + H2O + energy (ATP). Anaerobic: yeast makes ethanol and CO2; muscles make lactic acid. Glycolysis happens in the cytoplasm; Krebs cycle in the mitochondria.","Formula: C6H12O6 + 6O2 gives 6CO2 + 6H2O + energy","Watch out: Respiration is not breathing","Watch out: Stomata close at night, open in day"],"tip":"Respiration is not breathing","example":"Yeast fermenting sugar gives CO2 bubbles."},{"id":"excretion-and-osmoregulation","title":"Excretion and osmoregulation","summary":"Excretion removes waste products (CO2, urea, water, salts)","points":["Excretion removes waste products (CO2, urea, water, salts). Kidney: nephron filters blood, reabsorbs useful materials, produces urine. Lungs excrete CO2 and water vapour; skin excretes sweat (urea, salts).","Watch out: Egestion (faeces) is not excretion","Watch out: Urea is made in the liver"],"tip":"Egestion (faeces) is not excretion","example":"ADH increases water reabsorption in the kidney tubules."},{"id":"support-and-movement","title":"Support and movement","summary":"Plants: turgid cells, collenchyma and sclerenchyma give support","points":["Plants: turgid cells, collenchyma and sclerenchyma give support. Tropisms are directional responses (phototropism, geotropism). Animals: exoskeleton (chitin, insects) and endoskeleton (bone, vertebrates). Joints: hinge, ball and socket, pivot.","Watch out: Chitin is in arthropod exoskeletons, not bone","Watch out: Cartilage is flexible, bone is hard"],"tip":"Chitin is in arthropod exoskeletons, not bone","example":"Roots grow downwards: positive geotropism."},{"id":"reproduction","title":"Reproduction","summary":"Asexual: binary fission, budding (yeast), vegetative propagation (tubers, runners)","points":["Asexual: binary fission, budding (yeast), vegetative propagation (tubers, runners). Sexual: flowers have stamen (male, anther makes pollen) and carpel (female, ovary holds ovules). Fertilisation happens in the fallopian tube in humans.","Watch out: Pollination (transfer of pollen) is not fertilisation (fusion of gametes)","Watch out: Anther makes pollen; ovary makes eggs (ovules)"],"tip":"Pollination (transfer of pollen) is not fertilisation (fusion of gametes)","example":"Yeast reproduces asexually by budding."},{"id":"coordination-and-control","title":"Coordination and control","summary":"Nervous system: neurone, reflex arc, brain and spinal cord","points":["Nervous system: neurone, reflex arc, brain and spinal cord. Hormones are chemical messengers from endocrine glands. Insulin lowers blood sugar; adrenaline raises heart rate. In plants, auxins control growth.","Watch out: Insulin from pancreas, adrenaline from adrenal gland","Watch out: Hormones travel in blood; nerves are fast electrical signals"],"tip":"Insulin from pancreas, adrenaline from adrenal gland","example":"Knee-jerk reflex: sensory neurone to spinal cord to motor neurone, no brain needed."},{"id":"ecology-and-ecosystems","title":"Ecology and ecosystems","summary":"Producers, consumers (primary, secondary, tertiary), decomposers","points":["Producers, consumers (primary, secondary, tertiary), decomposers. Food chains and webs show energy flow (about 10% passes to next level). Nitrogen cycle: nitrogen fixation by bacteria, nitrification, denitrification. Population changes depend on birth, death and migration.","Watch out: Energy is lost as heat; matter is recycled","Watch out: Decomposers recycle nutrients"],"tip":"Energy is lost as heat; matter is recycled","example":"Grass to goat to lion: goat is a primary consumer."},{"id":"heredity-and-variation","title":"Heredity and variation","summary":"Genes are carried on chromosomes","points":["Genes are carried on chromosomes. Alleles: dominant (capital letter) and recessive (small letter). Mendel's laws predict ratios. Sickle-cell and Rhesus factor matter for marriage counselling. Sex-linked traits are carried on the X chromosome.","Formula: Monohybrid cross: Aa x Aa gives 1:2:1 genotype, 3:1 phenotype","Watch out: Phenotype is what you see; genotype is the gene pair","Watch out: Variation can be continuous (height) or discontinuous (blood group)"],"tip":"Phenotype is what you see; genotype is the gene pair","example":"Two carriers (AS x AS) have a 1 in 4 chance of a child with sickle-cell disease (SS)."},{"id":"evolution","title":"Evolution","summary":"Organisms change over generations by natural selection: variation, competition, survival of the fittest, inheritance","points":["Organisms change over generations by natural selection: variation, competition, survival of the fittest, inheritance. Evidence: fossils, comparative anatomy (homologous structures), embryology.","Watch out: Organisms do not evolve on purpose","Watch out: Homologous = same origin; analogous = same function, different origin"],"tip":"Organisms do not evolve on purpose","example":"Antibiotic-resistant bacteria are a natural selection example."}]},{"slug":"government","name":"Government","tryHash":"#/subject/government","topics":[{"id":"basic-concepts-power-authority-state-nat","title":"Basic concepts: power, authority, state, nation","summary":"Power is the ability to make others act","points":["Power is the ability to make others act. Authority is power that people accept as right. Legitimacy is acceptance by the people. Sovereignty means supreme power. A state has population, territory, government and sovereignty. A nation is a group sharing identity, culture or history.","Watch out: Nation and state are not the same (Nigeria is a state with many nations)","Watch out: Sovereignty belongs to the state, not the government"],"tip":"Nation and state are not the same (Nigeria is a state with many nations)","example":"A police officer has authority; a bandit has only power."},{"id":"forms-of-government","title":"Forms of government","summary":"Monarchy: rule by one hereditary ruler","points":["Monarchy: rule by one hereditary ruler. Aristocracy: rule by a few best. Oligarchy: rule by a small group for interest. Autocracy: rule by one person without limits. Democracy: rule by the people, directly or through representatives.","Watch out: Democracy means rule of the people, not rule by the majority only","Watch out: Republic: head of state is elected or chosen, not hereditary"],"tip":"Democracy means rule of the people, not rule by the majority only","example":"The UK has a constitutional monarchy; Nigeria is a democracy."},{"id":"arms-of-government","title":"Arms of government","summary":"Legislature makes laws","points":["Legislature makes laws. Executive implements laws. Judiciary interprets laws and settles disputes. Separation of powers means each arm works independently; checks and balances stop abuse.","Watch out: The legislature passes laws; it does not enforce them","Watch out: Unicameral: one chamber; bicameral: two chambers"],"tip":"The legislature passes laws; it does not enforce them","example":"The National Assembly passes a bill; the President signs it; the courts review it."},{"id":"structures-of-governance-unitary-federal","title":"Structures of governance: unitary, federal, confederal","summary":"Unitary: power is centralised","points":["Unitary: power is centralised. Federal: power is shared between central and state governments by a constitution (Nigeria). Confederal: independent states join a loose union with weak central power.","Watch out: Federalism has a written constitution, a division of powers and a supreme court","Watch out: Confederation can be dissolved more easily"],"tip":"Federalism has a written constitution, a division of powers and a supreme court","example":"Nigeria is federal: 36 states plus FCT."},{"id":"systems-of-governance-presidential-parli","title":"Systems of governance: presidential, parliamentary, monarchical","summary":"Presidential: the president is head of state and government, separate from the legislature (USA, Nigeria)","points":["Presidential: the president is head of state and government, separate from the legislature (USA, Nigeria). Parliamentary: the head of government is the leader of the majority party in parliament (UK). Monarchical: a king or queen is head of state.","Watch out: Presidential and parliamentary differ in separation of powers","Watch out: Monarchy does not always mean absolute monarchy"],"tip":"Presidential and parliamentary differ in separation of powers","example":"Nigeria uses the presidential system."},{"id":"constitution","title":"Constitution","summary":"A constitution is the supreme law that sets up government and protects rights","points":["A constitution is the supreme law that sets up government and protects rights. Sources: statutes, common law, conventions, treaties. Written (Nigeria, USA) or unwritten (UK). Rigid (hard to amend) or flexible (easy to amend).","Watch out: 'Unwritten' does not mean no constitution","Watch out: Rigid constitutions need special procedure to amend"],"tip":"'Unwritten' does not mean no constitution","example":"The UK constitution is unwritten and flexible."},{"id":"principles-of-democratic-government","title":"Principles of democratic government","summary":"Rule of law, separation of powers, checks and balances, accountability, individual and collective responsibility, representative government, constitutionalism, ","points":["Rule of law, separation of powers, checks and balances, accountability, individual and collective responsibility, representative government, constitutionalism, ethics in public office.","Watch out: Rule of law means no one is above the law","Watch out: Accountability goes with transparency"],"tip":"Rule of law means no one is above the law","example":"A minister who resigns after a scandal shows individual responsibility."},{"id":"process-of-legislation","title":"Process of legislation","summary":"A bill is introduced, debated, voted, passed by both chambers, then assented to by the head of state","points":["A bill is introduced, debated, voted, passed by both chambers, then assented to by the head of state. Delegated legislation (bye-laws, regulations) is made by bodies under powers from an Act. Decrees and edicts are made by military or authoritarian rulers.","Watch out: Bills become Acts after assent","Watch out: Decrees bypass parliament"],"tip":"Bills become Acts after assent","example":"A bye-law made by a local council is delegated legislation."},{"id":"citizenship","title":"Citizenship","summary":"Citizenship is membership of a state with rights and duties","points":["Citizenship is membership of a state with rights and duties. Ways to acquire: birth, registration, naturalisation, marriage. Duties: obey laws, pay taxes, defend the nation, vote. Dual citizenship allowed in some countries.","Watch out: Citizenship is not the same as residence","Watch out: Renunciation: giving up citizenship by choice"],"tip":"Citizenship is not the same as residence","example":"Citizenship by birth in Nigeria: born to a Nigerian parent."},{"id":"electoral-process","title":"Electoral process","summary":"Suffrage is the right to vote","points":["Suffrage is the right to vote. Electoral systems: first-past-the-post, proportional representation. Free and fair elections need an independent electoral commission (INEC in Nigeria), secret ballot, a register of voters.","Watch out: Proportional representation shares seats by vote share","Watch out: INEC conducts elections in Nigeria"],"tip":"Proportional representation shares seats by vote share","example":"First-past-the-post: the candidate with the most votes wins, even without a majority."},{"id":"political-parties-party-systems-and-pres","title":"Political parties, party systems and pressure groups","summary":"Political parties contest elections to form government","points":["Political parties contest elections to form government. Party systems: one-party, two-party, multiparty. Pressure groups influence government but do not seek power directly (labour unions, NBA).","Watch out: Pressure groups do not contest elections","Watch out: Party systems differ from party ideology"],"tip":"Pressure groups do not contest elections","example":"NLC is a pressure group; APC is a political party."},{"id":"public-opinion-and-civil-service","title":"Public opinion and civil service","summary":"Public opinion: the views of citizens, measured by polls, referendums, media","points":["Public opinion: the views of citizens, measured by polls, referendums, media. Civil service: permanent government employees who run government departments. It should be impartial and merit-based.","Watch out: Public opinion can be wrong or manipulated","Watch out: Civil servants are not elected"],"tip":"Public opinion can be wrong or manipulated","example":"Opinion polls measure public opinion."},{"id":"pre-colonial-and-colonial-nigeria","title":"Pre-colonial and colonial Nigeria","summary":"Pre-colonial: Hausa-Fulani emirates, Yoruba city-states (Oyo), Igbo decentralised village groups, Tiv segmentary system","points":["Pre-colonial: Hausa-Fulani emirates, Yoruba city-states (Oyo), Igbo decentralised village groups, Tiv segmentary system. Colonial: British trade, missionaries, company rule, crown colony and protectorate; direct rule (Lugard) and indirect rule; French assimilation and association.","Watch out: Igbo had no single centralised king","Watch out: Protectorate: British control without owning the land"],"tip":"Igbo had no single centralised king","example":"Indirect rule used existing emirs and chiefs to govern."},{"id":"decolonisation-and-nationalism","title":"Decolonisation and nationalism","summary":"Nationalism is the desire for self-rule","points":["Nationalism is the desire for self-rule. Nationalists: Herbert Macaulay, Nnamdi Azikiwe, Obafemi Awolowo, Ahmadu Bello, Aminu Kano. Parties: NCNC, AG, NPC. External forces: Pan-Africanism, WWII, Back-to-Africa.","Watch out: Dates and parties are often mixed up","Watch out: Independence was 1 October 1960"],"tip":"Dates and parties are often mixed up","example":"Macaulay is often called the father of Nigerian nationalism."},{"id":"constitutional-development-in-nigeria","title":"Constitutional development in Nigeria","summary":"Clifford (1922), Richards (1946), Macpherson (1951), Lyttleton (1954), Independence (1960)","points":["Clifford (1922), Richards (1946), Macpherson (1951), Lyttleton (1954), Independence (1960). Post-independence: 1963 (First Republic), 1979 (Second), 1989 (failed), 1999 (current).","Watch out: Remember the year of each constitution","Watch out: 1979 introduced presidential system"],"tip":"Remember the year of each constitution","example":"Richards Constitution introduced regional assemblies."},{"id":"foreign-policy-and-international-organis","title":"Foreign policy and international organisations","summary":"Foreign policy is a state's approach to other states","points":["Foreign policy is a state's approach to other states. Nigeria's foreign policy: African centrality, non-alignment, support for independence. Organisations: UN, AU/OAU, ECOWAS, Commonwealth, OPEC.","Watch out: OAU became AU in 2002","Watch out: Nigeria left the Commonwealth in 1995 and returned in 1999"],"tip":"OAU became AU in 2002","example":"ECOWAS promotes economic integration in West Africa."}]},{"slug":"physics","name":"Physics","tryHash":"#/subject/physics","topics":[{"id":"measurements-and-units","title":"Measurements and units","summary":"Every physical quantity is a number plus a unit","points":["Every physical quantity is a number plus a unit. SI base units: metre (length), kilogram (mass), second (time). Use a micrometer screw gauge for thin objects (about 0.01 mm), a vernier caliper for small lengths (about 0.1 mm), a metre rule for longer ones.","Formula: Area of rectangle = l x w","Formula: Volume of cuboid = l x w x h","Formula: Density = mass / volume","Watch out: Convert cm to m before finding SI volume (1 cm3 = 10⁻⁶ m3)","Watch out: Standard form: 0.00052 = 5.2 ×10⁻⁴"],"tip":"Convert cm to m before finding SI volume (1 cm3 = 10⁻⁶ m3)","example":"A block is 4 cm x 3 cm x 2 cm. Volume = 4 × 3 x 2 = 24 cm3."},{"id":"dimensions","title":"Dimensions","summary":"Dimensions show what a quantity is made of: L (length), M (mass), T (time)","points":["Dimensions show what a quantity is made of: L (length), M (mass), T (time). Use them to check if an equation is correct (homogeneity).","Formula: Velocity = LT-1","Formula: Acceleration = LT-2","Formula: Force = MLT-2","Formula: Work/energy = ML2T-2","Watch out: Dimensions have no numbers; 2 and 5 are dimensionless","Watch out: Only same-dimension quantities can be added"],"tip":"Dimensions have no numbers; 2 and 5 are dimensionless","example":"Check F = ma: dimension of ma = M x LT-2 = MLT-2, same as force, so it is consistent."},{"id":"scalars-and-vectors","title":"Scalars and vectors","summary":"Scalars have magnitude only (speed, mass, time, distance)","points":["Scalars have magnitude only (speed, mass, time, distance). Vectors have magnitude and direction (velocity, force, displacement, acceleration).","Formula: Resultant of perpendicular vectors: R = √(A² + B²)","Formula: Resolve: Ax = A cos θ, Ay = A sin θ","Watch out: Distance is scalar, displacement is vector","Watch out: Speed is scalar, velocity is vector"],"tip":"Distance is scalar, displacement is vector","example":"Forces 3 N east and 4 N north: R = √(9 + 16) = 5 N."},{"id":"motion-in-a-straight-line","title":"Motion in a straight line","summary":"Speed = distance / time","points":["Speed = distance / time. Velocity includes direction. Acceleration = change in velocity / time. The gradient of a distance-time graph is speed; the gradient of a velocity-time graph is acceleration; the area under a velocity-time graph is distance.","Formula: v = u + at","Formula: s = ut + 1/2 at2","Formula: v² = u² + 2as","Formula: a = (v - u)/t","Watch out: Use the same units for everything (m, s)","Watch out: Acceleration is negative when slowing down (deceleration)"],"tip":"Use the same units for everything (m, s)","example":"A car goes from 0 to 20 m/s in 5 s. a = (20 - 0)/5 = 4 m/s2."},{"id":"motion-under-gravity-and-projectiles","title":"Motion under gravity and projectiles","summary":"Free fall: a = g = 10 m/s2 (approx)","points":["Free fall: a = g = 10 m/s2 (approx). Projectiles move in a curve: horizontal velocity stays constant, vertical is affected by gravity.","Formula: Max height H = u² sin²θ / 2g","Formula: Time of flight T = 2u sin θ / g","Formula: Range R = u² sin 2θ / g","Watch out: At max height the vertical velocity is 0 (not the acceleration)","Watch out: Angle of 45 degrees gives the maximum range"],"tip":"At max height the vertical velocity is 0 (not the acceleration)","example":"Ball thrown up at 20 m/s: max height = 20 × 20 / (2 × 10) = 20 m."},{"id":"newton-s-laws-of-motion","title":"Newton's laws of motion","summary":"First law: inertia, a body stays at rest or uniform motion unless a force acts","points":["First law: inertia, a body stays at rest or uniform motion unless a force acts. Second law: F = ma. Third law: every action has an equal and opposite reaction. Impulse = Ft = change in momentum. Momentum = mv.","Formula: F = ma","Formula: p = mv","Formula: Impulse = Ft = m(v - u)","Watch out: Mass is the same on Earth and Moon; weight changes","Watch out: Momentum is conserved only when no external force acts"],"tip":"Mass is the same on Earth and Moon; weight changes","example":"A 4 kg body moves at 5 m/s. Momentum = 4 × 5 = 20 kg m/s."},{"id":"circular-motion","title":"Circular motion","summary":"A body moving in a circle is always accelerating (direction changes)","points":["A body moving in a circle is always accelerating (direction changes). Centripetal force points to the centre. Angular velocity omega = 2 π / T.","Formula: Centripetal force = mv2 / r","Formula: omega = v / r","Formula: omega = 2 π f","Watch out: Centripetal force is not an extra force; it is provided by tension, friction or gravity","Watch out: Centrifugal force is a pseudo-force seen from the rotating frame"],"tip":"Centripetal force is not an extra force; it is provided by tension, friction or gravity","example":"A 2 kg mass at 3 m/s on a 1.5 m radius: F = 2 × 9 / 1.5 = 12 N."},{"id":"simple-harmonic-motion-shm","title":"Simple harmonic motion (SHM)","summary":"SHM is motion where acceleration is proportional to displacement and directed to equilibrium","points":["SHM is motion where acceleration is proportional to displacement and directed to equilibrium. Speed is maximum at equilibrium, zero at the extremes. Energy changes between kinetic and potential, total stays the same.","Formula: T = 1/f","Formula: Period T = 2 π √(l/g) for a simple pendulum","Watch out: Frequency is cycles per second (Hz), period is seconds per cycle","Watch out: At the ends KE is zero, at the middle PE is zero"],"tip":"Frequency is cycles per second (Hz), period is seconds per cycle","example":"A body vibrates at 4 Hz: T = 1/4 = 0.25 s."},{"id":"work-energy-and-power","title":"Work, energy and power","summary":"Work = force x displacement in the direction of force","points":["Work = force x displacement in the direction of force. Kinetic energy and potential energy are forms of energy. Power = work / time. Gravity is a conservative force.","Formula: W = Fs","Formula: KE = 1/2 mv2","Formula: PE = mgh","Formula: P = W/t","Watch out: Work is zero if force and displacement are perpendicular","Watch out: Energy is conserved, not created"],"tip":"Work is zero if force and displacement are perpendicular","example":"Force 10 N moves a body 5 m: W = 50 J."},{"id":"gravitation","title":"Gravitation","summary":"Every mass attracts every other mass","points":["Every mass attracts every other mass. Force depends on the product of masses and the inverse square of distance. Weight = mg; mass stays the same everywhere.","Formula: F = G m1 m2 / r²","Formula: Escape velocity from Earth about 11.2 km/s","Watch out: Weight is a force (N), mass is in kg","Watch out: Weightlessness in orbit happens because the object is in free fall"],"tip":"Weight is a force (N), mass is in kg","example":"If distance doubles, force falls to one quarter."},{"id":"waves-and-sound","title":"Waves and sound","summary":"A wave transfers energy, not matter","points":["A wave transfers energy, not matter. Wave speed v = f lambda. Transverse waves vibrate across direction of travel; longitudinal waves vibrate along it (sound).","Formula: v = f lambda","Formula: f = 1/T","Watch out: Sound needs a medium","Watch out: Echo distance = speed x time / 2"],"tip":"Sound needs a medium","example":"Wavelength 0.5 m, frequency 340 Hz: v = 340 × 0.5 = 170 m/s."}]},{"slug":"chemistry","name":"Chemistry","tryHash":"#/subject/chemistry","topics":[{"id":"separation-of-mixtures-and-purification","title":"Separation of mixtures and purification","summary":"Mixtures are separated using differences in properties","points":["Mixtures are separated using differences in properties. Evaporation (salt from water), filtration (solid from liquid), decantation (immiscible liquids), distillation (liquids with different boiling points), magnetism (iron from sulphur), chromatography (dyes), sublimation (iodine, ammonium chloride).","Watch out: A pure substance has a sharp melting/boiling point; a mixture melts over a range","Watch out: Elements and compounds are both pure; mixtures are not"],"tip":"A pure substance has a sharp melting/boiling point; a mixture melts over a range","example":"Sea water to salt: evaporate the water, the salt stays."},{"id":"mole-concept-and-stoichiometry","title":"Mole concept and stoichiometry","summary":"One mole = 6.02 ×10²³ particles","points":["One mole = 6.02 ×10²³ particles. Molar mass is in g/mol. Use the balanced equation ratio to find moles needed.","Formula: moles = mass / molar mass","Formula: moles = number of particles / 6.02 ×10²³","Formula: moles = volume (dm3) / 22.4 at STP","Watch out: Balance the equation first","Watch out: Relative atomic mass uses C-12 = 12"],"tip":"Balance the equation first","example":"Mass of 2 mol of water (H2O, M = 18) = 36 g."},{"id":"chemical-combination-laws","title":"Chemical combination laws","summary":"Definite proportion (a compound always has the same mass ratio)","points":["Definite proportion (a compound always has the same mass ratio). Multiple proportion (two compounds of the same elements in simple whole number ratio). Conservation of mass. Gay-Lussac: gases combine in simple whole number volume ratios.","Formula: 1 vol H2 + 1 vol Cl2 gives 2 vol HCl","Watch out: Gay-Lussac applies to gases only, under the same temperature and pressure","Watch out: Avogadro: equal volumes of gases at same T and P have equal numbers of molecules"],"tip":"Gay-Lussac applies to gases only, under the same temperature and pressure","example":"1 dm3 H2 with 1 dm3 Cl2 gives 2 dm3 HCl."},{"id":"kinetic-theory-and-gas-laws","title":"Kinetic theory and gas laws","summary":"Solids, liquids and gases differ in particle spacing and movement","points":["Solids, liquids and gases differ in particle spacing and movement. Brownian motion supports the kinetic theory. Boyle: PV constant (T fixed). Charles: V/T constant (P fixed, use Kelvin). Combined and ideal gas law PV = nRT.","Formula: P1V1 = P2V2","Formula: V1/T1 = V2/T²","Formula: PV = nRT, R = 8.31 J/mol K","Watch out: Always convert to Kelvin (C + 273)","Watch out: Vapour density = M / 2"],"tip":"Always convert to Kelvin (C + 273)","example":"2 dm3 at 273 K heated to 546 K at constant pressure: V2 = 4 dm3."},{"id":"atomic-structure-and-isotopes","title":"Atomic structure and isotopes","summary":"Atoms contain protons (+), neutrons (0) in the nucleus and electrons (-) in shells","points":["Atoms contain protons (+), neutrons (0) in the nucleus and electrons (-) in shells. Atomic number = protons. Mass number = protons + neutrons. Isotopes have the same protons but different neutrons.","Formula: Neutrons = mass number - atomic number","Formula: Electron shells hold 2, 8, 8, 18","Watch out: Mass number is not atomic mass","Watch out: Ions: cations lose electrons, anions gain them"],"tip":"Mass number is not atomic mass","example":"Sodium: Z = 11, mass 23, neutrons = 12. Electron arrangement 2,8,1."},{"id":"periodic-table-and-periodicity","title":"Periodic table and periodicity","summary":"Elements are arranged by atomic number","points":["Elements are arranged by atomic number. Groups share valence electrons. Group 1 alkali metals, Group 7 halogens, Group 0/18 noble gases. Across a period atomic size falls and electronegativity rises; down a group atomic size rises.","Watch out: Noble gases are stable because their outer shell is full","Watch out: Transition metals are in the middle block"],"tip":"Noble gases are stable because their outer shell is full","example":"Chlorine (Group 7) is more electronegative than sodium (Group 1)."},{"id":"chemical-bonding","title":"Chemical bonding","summary":"Ionic bonds: metal to non-metal, electrons transferred (NaCl)","points":["Ionic bonds: metal to non-metal, electrons transferred (NaCl). Covalent bonds: non-metal to non-metal, electrons shared (H2O, CH4). Hydrogen bonding is a special intermolecular force (water). Metallic bonding is a sea of electrons.","Watch out: Covalent compounds have low melting points, ionic have high","Watch out: Coordinate bond: both electrons come from one atom"],"tip":"Covalent compounds have low melting points, ionic have high","example":"Water has hydrogen bonding, so it boils higher than expected."},{"id":"shapes-of-molecules","title":"Shapes of molecules","summary":"Molecular shape comes from electron pairs repelling each other","points":["Molecular shape comes from electron pairs repelling each other. CH4 is tetrahedral (109.5 degrees). NH3 is pyramidal (one lone pair). H2O is bent (two lone pairs). CO2 is linear.","Watch out: Lone pairs push the bonds closer, making the angle smaller","Watch out: Linear shapes: H2, O2, Cl2, HCl, CO2"],"tip":"Lone pairs push the bonds closer, making the angle smaller","example":"NH3: 3 bonded pairs + 1 lone pair = pyramidal."},{"id":"radioactivity-and-nuclear-chemistry","title":"Radioactivity and nuclear chemistry","summary":"Alpha: helium nucleus, stopped by paper","points":["Alpha: helium nucleus, stopped by paper. Beta: electron, stopped by aluminium. Gamma: electromagnetic wave, needs thick lead. Half-life: time for half the sample to decay.","Formula: Amount left = original x (1/2)^(number of half-lives)","Watch out: Nuclear reactions change the nucleus; chemical reactions change electrons","Watch out: Balance mass and atomic numbers in nuclear equations"],"tip":"Nuclear reactions change the nucleus; chemical reactions change electrons","example":"40 g with half-life 1 year: after 2 years 40 to 20 to 10 g."},{"id":"air-and-water","title":"Air and water","summary":"Air: nitrogen about 78%, oxygen about 21%, argon and other noble gases about 1%, CO2 small","points":["Air: nitrogen about 78%, oxygen about 21%, argon and other noble gases about 1%, CO2 small. Water: hard water has calcium/magnesium salts; temporary hardness is removed by boiling; permanent hardness needs washing soda. Water is a good solvent.","Watch out: Hygroscopic (absorbs water) vs deliquescent (absorbs and dissolves)","Watch out: Efflorescence: loses water of crystallisation in air"],"tip":"Hygroscopic (absorbs water) vs deliquescent (absorbs and dissolves)","example":"Temporary hard water boiled: carbonates precipitate out, water becomes soft."}]},{"slug":"economics","name":"Economics","tryHash":"#/subject/economics","topics":[{"id":"scarcity-choice-and-opportunity-cost","title":"Scarcity, choice and opportunity cost","summary":"Economics studies how scarce resources are allocated to meet unlimited wants","points":["Economics studies how scarce resources are allocated to meet unlimited wants. Every choice has an opportunity cost: the next best alternative given up. Factors of production are land (rent), labour (wages), capital (interest) and enterprise (profit).","Watch out: Opportunity cost is not the money spent","Watch out: Free goods like air are not scarce"],"tip":"Opportunity cost is not the money spent","example":"A farmer who uses land for maize gives up the cassava he could have grown: cassava is the opportunity cost."},{"id":"demand-supply-and-price","title":"Demand, supply and price","summary":"Law of demand: higher price, lower quantity demanded","points":["Law of demand: higher price, lower quantity demanded. Law of supply: higher price, higher quantity supplied. Equilibrium is where demand equals supply. A shift is a change in the whole curve (caused by income, tastes or prices of substitutes); a movement is change along the curve (caused by price).","Formula: Equilibrium: Qd = Qs","Watch out: Price change moves ALONG the curve; other factors SHIFT it","Watch out: Necessities (salt) tend to have inelastic demand"],"tip":"Price change moves ALONG the curve; other factors SHIFT it","example":"If tea rises in price, coffee (a substitute) demand rises."},{"id":"national-income-inflation-and-money","title":"National income, inflation and money","summary":"GDP is the total value of goods and services produced in a country","points":["GDP is the total value of goods and services produced in a country. Inflation is a sustained rise in the general price level; deflation is a fall. Money is a medium of exchange, unit of account and store of value. The CBN controls money supply in Nigeria.","Formula: Inflation rate = (CPI now - CPI before) / CPI before × 100","Watch out: Real GDP adjusts for inflation; nominal GDP does not","Watch out: Money is a medium of exchange, not wealth itself"],"tip":"Real GDP adjusts for inflation; nominal GDP does not","example":"If prices rise 10% in a year, the value of N100 falls."},{"id":"trade-banking-and-government","title":"Trade, banking and government","summary":"Balance of trade = exports minus imports","points":["Balance of trade = exports minus imports. Direct taxes (income tax) fall on income; indirect taxes (VAT) fall on spending. Commercial banks take deposits and give loans; the IMF helps with balance of payments problems. A common currency eases trade among members.","Watch out: Central bank is not the same as commercial bank","Watch out: Free trade means no barriers, not no government"],"tip":"Central bank is not the same as commercial bank","example":"Nigeria exports crude oil and imports refined products: a trade balance depends on the value of both."}]},{"slug":"literature","name":"Literature in English","tryHash":"#/subject/literature","topics":[{"id":"elements-of-prose-and-drama","title":"Elements of prose and drama","summary":"Plot is the sequence of events (exposition, rising action, climax, falling action, resolution)","points":["Plot is the sequence of events (exposition, rising action, climax, falling action, resolution). Characters: protagonist (main), antagonist (opposes). Setting is time and place. Tone is the writer's attitude. Point of view: first person (I) or third person (he/she). In drama, a soliloquy reveals a character's thoughts alone; dramatic irony means the audience knows more than the character.","Watch out: The narrator is not always the author","Watch out: Setting is time and place, not the theme"],"tip":"The narrator is not always the author","example":"In a tragedy the climax is the turning point before the hero's downfall."},{"id":"figures-of-speech","title":"Figures of speech","summary":"Metaphor: a thing is another (He is a lion)","points":["Metaphor: a thing is another (He is a lion). Simile: a comparison using like or as (as brave as a lion). Personification: human qualities given to things (the wind whispered). Hyperbole: deliberate exaggeration. Irony: a gap between what is said or expected and what happens. Alliteration: repeated consonant sounds at the start of words.","Watch out: Simile needs like or as; metaphor does not","Watch out: Hyperbole is exaggeration, not understatement"],"tip":"Simile needs like or as; metaphor does not","example":"'The sun smiled at us' is personification; 'the sun is a lamp' is metaphor."},{"id":"poetry-forms-and-devices","title":"Poetry: forms and devices","summary":"A stanza is a group of lines","points":["A stanza is a group of lines. A sonnet has 14 lines. An elegy mourns the dead. An epic tells of heroic deeds. Rhyme is the matching end sound of lines. Rhythm and metre count stresses: iambic pentameter has five iambs (da-DUM) per line.","Watch out: Rhyme depends on sound, not spelling","Watch out: A ballad tells a story in verse"],"tip":"Rhyme depends on sound, not spelling","example":"An ode praises a person or thing; an elegy laments a loss."}]},{"slug":"crs","name":"Christian Religious Studies","tryHash":"#/subject/crs","topics":[{"id":"creation-the-patriarchs-and-the-exodus","title":"Creation, the patriarchs and the Exodus","summary":"Genesis records creation in six days, with God resting on the seventh","points":["Genesis records creation in six days, with God resting on the seventh. Adam and Eve, Noah and the flood, Abraham (God's covenant), Isaac, Jacob and Joseph. Moses led the Exodus from Egypt and received the Ten Commandments on Mount Sinai.","Watch out: Know which book each story is in (Genesis, Exodus)","Watch out: Moses received the law; he did not write the whole Bible"],"tip":"Know which book each story is in (Genesis, Exodus)","example":"Abraham was tested with the sacrifice of Isaac (Genesis 22)."},{"id":"kings-judges-and-prophets","title":"Kings, judges and prophets","summary":"Judges were leaders such as Samson and Gideon","points":["Judges were leaders such as Samson and Gideon. Saul was the first king, then David (who defeated Goliath) and Solomon (who built the temple). Prophets such as Elijah confronted kings like Ahab; Daniel survived the lions' den.","Watch out: Solomon built the temple; David planned it","Watch out: Prophets spoke God's message to the people"],"tip":"Solomon built the temple; David planned it","example":"Elijah rebuked King Ahab over Naboth's vineyard (1 Kings 21)."},{"id":"the-life-and-teaching-of-jesus","title":"The life and teaching of Jesus","summary":"Jesus was born in Bethlehem and baptised by John the Baptist","points":["Jesus was born in Bethlehem and baptised by John the Baptist. His teaching includes the Sermon on the Mount (the Beatitudes), parables such as the lost son and the unforgiving servant, and the Lord's Prayer (Matthew 6). The Last Supper preceded his death; Pentecost is when the Holy Spirit came to the disciples.","Watch out: Judas betrayed Jesus; Peter denied him","Watch out: Pentecost is the day of the Holy Spirit's coming"],"tip":"Judas betrayed Jesus; Peter denied him","example":"The Great Commission (Matthew 28) sends the disciples to all nations."},{"id":"the-early-church-and-christian-living","title":"The early church and Christian living","summary":"Paul (once Saul) spread the gospel to the Gentiles","points":["Paul (once Saul) spread the gospel to the Gentiles. The fruit of the Spirit (Galatians 5:22) are love, joy, peace, patience, kindness, goodness, faithfulness, gentleness and self-control. Sacraments such as baptism and the Lord's Supper mark key moments of faith.","Watch out: Paul was originally named Saul","Watch out: Baptism is a sacrament; prayer is not counted as one"],"tip":"Paul was originally named Saul","example":"Love comes first in the list of fruit of the Spirit's qualities, followed by joy and peace."}]},{"slug":"commerce","name":"Commerce","tryHash":"#/subject/commerce","topics":[{"id":"trade-and-the-aids-to-trade","title":"Trade and the aids to trade","summary":"Commerce is trade plus the aids to trade: banking, transport, insurance, warehousing, advertising and communication","points":["Commerce is trade plus the aids to trade: banking, transport, insurance, warehousing, advertising and communication. Wholesalers sell in bulk to retailers; retailers sell in small quantities to final consumers.","Watch out: Wholesale is bulk to traders, retail is to consumers","Watch out: Warehousing stores goods; it is not transport"],"tip":"Wholesale is bulk to traders, retail is to consumers","example":"A market trader buying 100 bags of rice from a mill is a wholesaler's customer; the trader then sells to shoppers as a retailer."},{"id":"business-organisations","title":"Business organisations","summary":"Sole proprietorship: one owner, unlimited liability","points":["Sole proprietorship: one owner, unlimited liability. Partnership: 2 to 20 partners in Nigeria under CAMA, usually with unlimited liability. Limited company: shareholders' liability is limited to their shares. The CAC registers companies.","Watch out: Sole traders have unlimited liability","Watch out: Shareholders own a company; directors manage it"],"tip":"Sole traders have unlimited liability","example":"A company with 5 shareholders each holding N10,000 of shares risks only that money if it fails."},{"id":"banking-finance-and-documents","title":"Banking, finance and documents","summary":"A cheque is a written order to a bank to pay","points":["A cheque is a written order to a bank to pay. An overdraft lets you borrow beyond your balance up to a limit. A bill of exchange orders payment at a future date. The bill of lading shows goods shipped. An invoice is the seller's bill. A debit note increases what the buyer owes. A prospectus invites the public to buy shares.","Formula: Working capital = current assets - current liabilities","Watch out: Invoice (bill) vs debit note (adds to amount owed)","Watch out: Fixed assets are long-term (buildings); current assets are short-term (stock, debtors)"],"tip":"Invoice (bill) vs debit note (adds to amount owed)","example":"A debit note is issued when the seller undercharged the buyer."},{"id":"insurance-basics","title":"Insurance basics","summary":"Insurance spreads risk","points":["Insurance spreads risk. The insured pays a premium. The principle of indemnity means the insured is restored to the position before the loss but cannot profit. Utmost good faith means full disclosure of facts. Insurable interest means the insured would lose money by the loss.","Watch out: Premium is paid by the insured to the insurer","Watch out: Indemnity stops profit from a loss"],"tip":"Premium is paid by the insured to the insurer","example":"A shop insured for N500,000 that suffers a N200,000 fire can claim N200,000, not more."}]}];

// Added lessons: JAMB tricks + long formulas, chemistry boosters, biology memory hooks, government must-know numbers.
(function(){
  const L = window.LESSONS || [];
  const add = (slug, topics) => { const s = L.find(x => x.slug === slug); if (s) s.topics.push(...topics); };
  add("maths", [
    {id:"jamb-tricks-elimination-and-time", title:"JAMB tricks: elimination and time", summary:"Score faster: eliminate wrong options, estimate before you calculate, and never stay stuck on one question.", points:["Check the last digit first: if the options end in 2, 4, 6, 8 and your product ends in 5, eliminate them","Estimate: round numbers to nearest 10 or 100 to rule out options far away","Plug in the options: try the middle option in the question and move up or down","Time budget: about 1 minute per question, skip and return once if stuck for more than 40 seconds","Watch out: do not spend 3 minutes on one question while easy marks wait"], tip:"Mark your skip and come back. Easy marks first.", example:"A question asks for 37 × 48. Last digit of 7 × 8 is 6, so only options ending in 6 remain."},
    {id:"jamb-tricks-shortcut-math", title:"JAMB tricks: shortcut math", summary:"Fast mental methods for percentages, squares, and multiplying near 100.", points:["Squares ending in 5: 25² = 625 (take 2 × 3 = 6, then 25)","Multiply near 100: 97 × 98 = (100-3)(100-2) = 10000 - 500 + 6 = 9506","10% is shifting the decimal, 15% = 10% + half of 10%","Percent of a number: 35% of 200 = 10% × 3 (60) + 5% (10) = 70","Watch out: quick tricks must still give the right answer, check your last digit"], tip:"Use the trick only when the numbers look friendly.", example:"25% of 480 = 480 ÷ 4 = 120."},
    {id:"long-formula-handling", title:"Long formulas: how to handle them", summary:"Break any long formula into parts, substitute carefully, and check units.", points:["Write the formula first, then list every value you know with its symbol","Substitute one value at a time, use brackets for negatives: (-3)² = 9, not -9","Do multiplications and divisions in order before adding, or use a calculator for long decimals","Check units match before you finish: convert cm to m, minutes to hours","Watch out: √(a+b) is not √a + √b"], tip:"Write the formula, substitute, simplify, then check the units.", example:"Distance = √((x₂ - x₁)² + (y₂ - y₁)²). Points (1,2) and (4,6): √(3² + 4²) = √25 = 5."}
  ]);
  add("chemistry", [
    {id:"chemistry-boosters", title:"Chemistry boosters: mole shortcuts, balancing fast, periodic patterns", summary:"Quick methods that save time in JAMB chemistry.", points:["Mole shortcut: moles = mass ÷ molar mass; particles = moles × 6.02 × 10²³","Gas shortcut at STP: moles = volume in dm³ ÷ 22.4","Balancing: balance metals first, then non-metals, then oxygen, then hydrogen last","Periodic trend: atomic size goes down across a period and up down a group","Group number: Group 1 has 1 valence electron, Group 7 has 7, Group 0 has a full shell","Watch out: the balancing check is the same count of each atom on both sides"], tip:"Balance metals first, hydrogen and oxygen last.", example:"Mg + O₂ → MgO. Balance: 2Mg + O₂ → 2MgO."}
  ]);
  add("biology", [
    {id:"biology-memory-hooks", title:"Biology memory hooks", summary:"Short hooks to remember tricky biology facts.", points:["Mitochondria: the powerhouse, makes ATP by respiration","Xylem carries water up, phloem carries food down (X for up, P for down)","Osmosis: water moves from high water potential to low water potential","Kingdom mnemonic: King Phillip Came Over For Good Spaghetti (Kingdom, Phylum, Class, Order, Family, Genus, Species)","Watch out: aerobic respiration makes CO₂ and water, anaerobic makes lactic acid in animals"], tip:"Build a silly sentence for each list and say it aloud.", example:"Kingdom, Phylum, Class, Order, Family, Genus, Species: King Phillip Came Over For Good Spaghetti."}
  ]);
  add("government", [
    {id:"constitution-must-know-numbers", title:"Constitution must-know numbers", summary:"Key figures from the Nigerian constitution that JAMB asks about.", points:["Age of presidential candidate: 40 years (Section 131)","President's term: 4 years, maximum 2 terms","Senate: 109 members; House of Representatives: 360 members","Number of states: 36 plus the FCT","Minimum age for House of Representatives: 25 years","Watch out: check the exact year and section you are asked about"], tip:"Learn the numbers as a set: 40, 4, 2, 36, 109, 360.", example:"A president serves a maximum of 2 terms of 4 years each, so 8 years in total."}
  ]);
})();
